{
  "objectives": [
    {
      "segments": [1, 2, 3],
      "goal": "Explain the meaning of virtual reality through the dictionary meanings of its terms and the characteristics of artificial environment, sensory immersion, and user interaction, and classify computer-aided design, video conferencing, and three-dimensional movie systems as non-VR.",
      "achieves": "Gives the learner a consistent definition and distinguishing criteria for VR that support later discussion of XR concepts, hardware, software, and system development."
    }
  ],
  "goal": "Explain the meaning of virtual reality through the dictionary meanings of its terms and the characteristics of artificial environment, sensory immersion, and user interaction, and classify computer-aided design, video conferencing, and three-dimensional movie systems as non-VR.",
  "achieves": "Provides the foundational vocabulary and classification criterion for VR that the course uses to explain XR technologies, human factors, and system design."
}

{
  "objectives": [
    {
      "segments": [1, 2, 3, 4, 5],
      "goal": "Describe the historical evolution of virtual reality by organizing its major developments into four phases with approximate time spans.",
      "achieves": "It gives the learner a chronological foundation for interpreting later course topics on XR hardware, software, and immersive user experience."
    }
  ],
  "goal": "Describe the historical evolution of virtual reality from early stereoscopic devices through the growth phase of commercial headsets and the metaverse using a four-phase framework.",
  "achieves": "It supports the course aim of building foundational XR knowledge by helping the learner understand how key immersive technologies and terminology developed before studying current system development and optimization."
}

{
  "objectives": [
    {
      "segments": [
        1,
        2,
        3
      ],
      "goal": "Explain why the goal of presence in VR is ambiguous and how the uncanny valley effect, together with representational, interaction, and experiential fidelity, shapes design trade-offs for realistic VR experiences.",
      "achieves": "It lets the learner evaluate VR experiences and design decisions by understanding the perceptual and experiential constraints that affect presence and immersion."
    },
    {
      "segments": [
        4
      ],
      "goal": "Describe the main technological challenges of AR systems across display technology, interaction modalities, and three-dimensional pose registration and tracking.",
      "achieves": "It lets the learner identify the technical problems an AR developer must address to align and sustain virtual content within the real environment."
    }
  ],
  "goal": "Explain the major issues and challenges of VR and AR, from the ambiguity of presence and fidelity constraints in VR to the display, interaction, and pose registration/tracking challenges in AR.",
  "achieves": "It provides a foundation for understanding the user-facing and technological limitations of XR systems, supporting later design and implementation of XR applications."
}

{
  "objectives": [
    {
      "segments": [1, 2],
      "goal": "Explain how machine-learning-based cybersickness evaluation methods are characterized by their task, output type, and model interpretability.",
      "achieves": "It lets the learner understand what sickness-monitoring options are available when evaluating or developing an XR system and how to interpret their results."
    },
    {
      "segments": [3, 4, 5],
      "goal": "Explain how cybersickness is mitigated in XR by balancing presence against comfort, including developer-side and user-side countermeasures.",
      "achieves": "It lets the learner reduce cybersickness in XR use or design by selecting appropriate technical or user-centered measures while understanding their effect on presence."
    }
  ],
  "goal": "Explain how cybersickness is evaluated and mitigated in XR systems, using machine-learning-based detection or prediction methods and developer- or user-side countermeasures that balance presence.",
  "achieves": "It gives the learner a foundation for addressing a key psycho-physiological issue in XR, so they can choose sickness-evaluation methods and apply countermeasures with confidence when understanding or implementing XR systems."
}

{
  "objectives": [
    {
      "segments": [1, 2, 3],
      "goal": "Explain how AR software is organized into rapid prototyping, plugin-to-existing-tools, and standalone authoring categories, and describe the representative tools and practical characteristics of each category.",
      "achieves": "This gives the learner a basis for comparing and selecting AR software when planning and building an AR system."
    }
  ],
  "goal": "Explain the AR software landscape by identifying its main categories and the representative tools and practical characteristics associated with each category.",
  "achieves": "This supports the learner in choosing suitable AR tools for software development in the course's XR system case study."
}

{
  "objectives": [
    {
      "segments": [1, 2],
      "goal": "Explain the main application domains of augmented reality and illustrate them with examples from consumer/customer experience and healthcare, emphasizing augmentation of real-world content rather than immersion.",
      "achieves": "It helps the learner recognize where AR is used and what user tasks it supports, which prepares them to gather requirements and evaluate use cases for an XR system."
    },
    {
      "segments": [3],
      "goal": "Classify AR systems into marker-based and markerless categories and identify the location-based, superimposition-based, projection-based, and outlining-based markerless techniques.",
      "achieves": "It gives the learner a technical taxonomy for recognizing the sensing, tracking, and presentation methods behind AR applications, supporting later hardware, software, and design decisions."
    }
  ],
  "goal": "Explain the main application domains of augmented reality and classify AR systems into marker-based and markerless categories.",
  "achieves": "It gives the learner a foundation for understanding what AR applications are for and how they are technically distinguished, which supports later XR hardware/software analysis and system development."
}

{
  "objectives": [
    {
      "segments": [1],
      "goal": "Explain how audio supports believable and present XR experiences by complementing visual information.",
      "achieves": "Gives the learner a basis for recognizing audio as a key human factor when evaluating or designing immersive XR systems."
    },
    {
      "segments": [2, 3],
      "goal": "Trace how sound waves are physically characterized and converted by the human auditory system into neural impulses.",
      "achieves": "Provides the physical and perceptual foundations needed to understand why and how audio shapes immersion in XR."
    }
  ],
  "goal": "Explain how audio contributes to immersive XR experiences by connecting sound's physical properties and human hearing to believability and presence.",
  "achieves": "Equips the learner with foundational human-factors knowledge for understanding and later addressing the auditory dimension in XR system design and implementation."
}

{
  "objectives": [
    {
      "segments": [1],
      "goal": "Explain the commercial promise of XR by describing its major current VR application domains.",
      "achieves": "Provides practical context for understanding why XR systems are pursued and which use cases motivate later hardware, software, and design choices."
    },
    {
      "segments": [2],
      "goal": "Classify VR systems as non-immersive, semi-immersive, or fully immersive based on the degree of sensory blocking.",
      "achieves": "Gives a basis for comparing VR systems and experiences, supporting later study of hardware, user experience, and optimization."
    }
  ],
  "goal": "Describe the scope and variety of VR by identifying its major application domains and its immersion-based system categories.",
  "achieves": "Gives foundational orientation for the course by clarifying where VR is used and how VR systems are distinguished, preparing the learner for later hardware, human factors, and development topics."
}

{
  "objectives": [
    {
      "segments": [1, 2, 3],
      "goal": "Explain the foundational definitions of augmented reality, virtual reality, and mixed reality, including the identifying characteristics of augmented reality, the difference between augmented and virtual reality, the reality-virtuality continuum, and the course's treatment of mixed reality as augmented reality.",
      "achieves": "Gives the learner a common vocabulary and conceptual framework for AR, VR, and MR to use when studying later course topics on XR hardware, human factors, system development, and optimization."
    }
  ],
  "goal": "Explain the foundational definitions of augmented reality, virtual reality, and mixed reality, including the identifying characteristics of augmented reality, the difference between augmented and virtual reality, the reality-virtuality continuum, and the course's treatment of mixed reality as augmented reality.",
  "achieves": "Provides the learner with the basic XR terminology needed to follow later explanations of XR systems and to build toward understanding and implementing an XR system."
}

{
  "objectives": [
    {
      "segments": [1, 2, 3, 4, 5],
      "goal": "Describe the progression of augmented reality through its four historical phases, including the key developments, systems, and commercial factors that defined each phase.",
      "achieves": "Gives learners a historical context for AR tracking, display, interaction, and application technologies, helping them follow later XR system topics."
    }
  ],
  "goal": "Trace the evolution of augmented reality from experimental research to commercial application, explaining the phases, key developments, and driving factors in each stage.",
  "achieves": "Supports the course aim of building foundational XR knowledge by situating augmented reality technologies and applications in their historical development."
}

{
  "objectives": [
    {
      "segments": [1, 2, 3, 4],
      "goal": "Explain how visual motion, locomotion methods, control, display and content characteristics, and exposure factors influence the onset and severity of cybersickness in virtual environments.",
      "achieves": "It helps the learner understand a key psycho-physiological issue and anticipate which VR design or content choices may increase user discomfort."
    },
    {
      "segments": [5, 6, 7, 8],
      "goal": "Describe the input-process-output framework for measuring cybersickness, its four input categories, and the distinction between manual and machine-learning-based evaluation.",
      "achieves": "It enables the learner to choose and interpret sickness questionnaires, physiological signals, behavioral measures, and model-based assessments when evaluating an XR experience."
    }
  ],
  "goal": "Explain how cybersickness in virtual environments arises and how its occurrence and severity can be measured and evaluated.",
  "achieves": "It gives the learner foundational knowledge for identifying discomfort risks and selecting appropriate assessment methods when designing, implementing, or optimizing an XR system."
}

{
  "objectives": [
    {
      "segments": [1, 2, 3, 4],
      "goal": "Describe the user-centered and usability foundations that guide interactive-system design.",
      "achieves": "It lets the learner apply user expertise categories, user characteristics, usability measures, and design-lifecycle perspectives when planning or evaluating an interactive system."
    },
    {
      "segments": [5],
      "goal": "Explain how XR systems function as interactive systems and how user-centered design applies to their input and output design.",
      "achieves": "It lets the learner connect general interactive-system design to XR engines, input devices, output devices, and perception, supporting later human-factors and system-development topics."
    }
  ],
  "goal": "Explain how user-centered interactive-system design principles apply to XR systems, especially their input and output design.",
  "achieves": "It prepares the learner to understand later human-factors topics and to design or evaluate XR systems from the user's perspective with confidence."
}

{
  "objectives": [
    {
      "segments": [1, 2, 3],
      "goal": "Describe the augmented reality software tool landscape, organizing tools by developer skill, target platform, or tracking technology and identifying representative low-level and rapid-prototyping tools.",
      "achieves": "Gives the learner a foundation for identifying relevant AR software options when planning an XR application, supporting the course aim of understanding and implementing XR systems with confidence."
    }
  ],
  "goal": "Explain how augmented reality software tools are organized by developer skill, target platform, or tracking technology and distinguish low-level libraries and frameworks from rapid-prototyping authoring tools with representative examples.",
  "achieves": "Prepares the learner to reason about AR software choices in the later design and implementation stages of building an XR system."
}

{
  "objectives": [
    {
      "segments": [1, 2, 3],
      "goal": "Describe the complete view of a virtual reality system as comprising the user/organism, VR hardware, and surrounding physical environment, and explain how stimulation and tracking data flows connect them.",
      "achieves": "Equips the learner with a system-level understanding of VR interaction that supports later study of VR/AR hardware, software, human factors, and system design."
    },
    {
      "segments": [4, 5, 6],
      "goal": "Identify the three main functional categories of VR hardware and describe the major hand-based and non-hand-based input devices, their examples, trade-offs, and the reason multimodal input is preferred.",
      "achieves": "Supports the learner in recognizing appropriate VR hardware options and input modalities when understanding requirements, designing, or implementing an XR system."
    }
  ],
  "goal": "Describe the complete view of a virtual reality system and classify its main hardware categories and input-device types.",
  "achieves": "Provides the foundational hardware and system model needed to follow later XR hardware/software, human-factors, development, and optimization topics and to implement an XR system with confidence."
}

{
  "objectives": [
    {
      "segments": [1, 2],
      "goal": "Introduce the Majuli case study and explain why the island’s tangible, intangible, and ecological heritage requires preservation because of river erosion.",
      "achieves": "Gives the learner the problem context for the course’s XR case study, so later requirement, design, and implementation work can be understood as responses to a real heritage-preservation need."
    },
    {
      "segments": [3, 4],
      "goal": "Explain why digital immersive preservation with virtual reality is useful for Majuli and describe the goals of the Majuli VR system.",
      "achieves": "Lets the learner frame the Majuli project as an XR system intended to create a multimedia heritage archive and provide an immersive virtual tour, preparing them for the subsequent system-development lectures."
    }
  ],
  "goal": "Summarize the Majuli case study by explaining its heritage-preservation problem, the suitability of VR for digital heritage preservation, and the goals of the proposed VR system.",
  "achieves": "Equips the learner to understand the course’s running XR case study and follow the later stages of developing and implementing an XR system around a real heritage-preservation scenario."
}

{
  "objectives": [
    {
      "segments": [1],
      "goal": "Explain how virtual reality systems capture user input without hand controllers, including full-body tracking and sound-based tracking methods.",
      "achieves": "Gives the learner a basis for identifying non-hand input hardware and understanding how movement and sound are captured in VR applications."
    },
    {
      "segments": [2],
      "goal": "Describe the processing component of virtual reality systems and how the GPU, CPU, and RAM support rendering and system performance.",
      "achieves": "Lets the learner understand the computational requirements of VR and the factors that matter when choosing a processing platform or middleware."
    },
    {
      "segments": [3, 4],
      "goal": "Describe the main output devices of virtual reality systems and how visual displays and non-visual sensory devices support immersion.",
      "achieves": "Enables the learner to evaluate how different displays and sensory feedback technologies affect presence, usability, and the overall XR experience."
    }
  ],
  "goal": "Explain the main hardware elements of virtual reality systems, from non-hand input to processing and output devices, and how each supports immersion and interaction.",
  "achieves": "Provides the foundational VR hardware knowledge needed to understand later XR topics and to evaluate hardware choices for immersive systems."
}

{
  "objectives": [
    {
      "segments": [1, 2],
      "goal": "Explain the preparation of IMU motion data for XR tracking, from raw gyroscope, accelerometer, and magnetometer readings to calibrated sensor values.",
      "achieves": "Gives the learner a sensor-level foundation for understanding how low-cost XR tracking devices obtain trustworthy motion input."
    },
    {
      "segments": [3, 4],
      "goal": "Describe how an XR tracking system maintains orientation by registering an initial pose, integrating calibrated angular velocity, and applying drift correction.",
      "achieves": "Lets the learner understand how calibrated motion data become a maintained orientation estimate, supporting later work on XR system development and optimization."
    }
  ],
  "goal": "Explain how IMU-based XR tracking obtains usable sensor data and maintains an orientation estimate by calibrating IMU readings, registering and integrating orientation, and correcting drift.",
  "achieves": "Provides foundational understanding of XR tracking technology that helps the learner understand headset tracking, assess tracking issues, and later build or optimize XR systems."
}

{
  "objectives": [
    {
      "segments": [1, 2, 3, 4],
      "goal": "Describe how sensory signals become perception through the cerebral cortex's neural, hierarchical, and memory-based processing.",
      "achieves": "Gives the learner the perceptual foundation for analyzing how XR sensory input is experienced by users."
    },
    {
      "segments": [5, 6],
      "goal": "Explain how proprioception provides body-position and muscular-effort signals and how XR sensory conflicts can cause cybersickness or presence loss, and state a design implication for reducing such conflicts.",
      "achieves": "Enables the learner to recognize human-factors causes of XR discomfort and presence loss and relate them to design choices in immersive systems."
    }
  ],
  "goal": "Explain how human perception and proprioception arise from neural and motor processing, how XR sensory conflicts can cause cybersickness or presence loss, and state a design implication for reducing such conflicts.",
  "achieves": "Provides the human-factors foundation for evaluating XR experiences and addressing psycho-physiological issues in XR system development."
}

{
  "objectives": [
    {
      "segments": [1, 2],
      "goal": "Explain the scope of tracking in XR systems, from why it is needed to the main categories of tracked entities.",
      "achieves": "Gives the learner the shared terminology and conceptual distinctions needed to discuss VR and AR tracking requirements and user interaction with virtual or mixed content."
    },
    {
      "segments": [3, 4],
      "goal": "Describe the structure of tracking in XR systems, from tracker placement to the main stages that turn sensor measurements into a tracked pose.",
      "achieves": "Enables the learner to understand how tracking hardware and software work and to reason about pose-related requirements in later XR system design and implementation."
    }
  ],
  "goal": "Explain the foundational model of tracking in XR systems, including its scope, tracker-placement methods, and process stages.",
  "achieves": "Provides the conceptual foundation for understanding XR hardware and software and for approaching the design and implementation of tracking in XR systems with confidence."
}

{
  "objectives": [
    {
      "segments": [1],
      "goal": "Explain how human-eye optics and VR headset lens setups form a real image on the retina that is perceived as a virtual image.",
      "achieves": "Gives the learner a physiological and optical foundation for understanding VR display hardware and why engineered lenses are needed to project virtual scenes onto the retina."
    },
    {
      "segments": [2, 3],
      "goal": "Describe the perceptual mechanisms that allow depth and motion to be experienced in three-dimensional XR scenes.",
      "achieves": "Helps the learner understand the human-factors basis of immersion and spatial interaction, preparing them to evaluate how XR experiences represent and move through virtual space."
    },
    {
      "segments": [4],
      "goal": "Relate human visual perception constraints to XR display requirements for spatial resolution, intensity, and temporal resolution.",
      "achieves": "Enables the learner to understand the criteria for resolution, brightness, and frame rate in XR displays and to recognize perceptual artifacts such as aliasing and the screen-door effect when evaluating or optimizing displays."
    }
  ],
  "goal": "Explain how human visual perception of XR scenes, from optical image formation to depth and motion, determines XR display requirements for resolution, intensity, and frame rate.",
  "achieves": "Provides the foundational human-factors and display knowledge needed to understand XR visual hardware, address psycho-physiological issues, and later design or optimize XR systems with confidence."
}

{
  "objectives": [
    {
      "segments": [1, 2, 3],
      "goal": "Classify the main XR tracking technologies and explain how electromechanical, electromagnetic, and acoustic/ultrasonic trackers measure pose.",
      "achieves": "It gives the learner a baseline for comparing sensor-based pose measurement options in VR and AR hardware."
    },
    {
      "segments": [4, 5, 6, 7, 8],
      "goal": "Explain how vision-based XR tracking systems estimate pose from camera and depth sensor observations.",
      "achieves": "It lets the learner compare inside-out and outside-in visual and depth approaches when selecting tracking for an XR application."
    },
    {
      "segments": [9],
      "goal": "Explain how inertial tracking and GPS/RTK provide positional tracking in XR and where their limitations occur.",
      "achieves": "It helps the learner understand self-contained and satellite-based position sources that complement camera-based tracking in system design."
    },
    {
      "segments": [10],
      "goal": "Describe how XR tracking can be extended to full-body motion, gaze, and hybrid multi-sensor systems.",
      "achieves": "It enables the learner to recognize how these methods support richer interaction and immersion in XR implementations."
    }
  ],
  "goal": "Classify and explain the main tracking technologies used to determine user and device pose in VR and AR.",
  "achieves": "It gives the learner the hardware/software foundation needed to evaluate tracking choices and later implement an XR system with confidence."
}

{
  "objectives": [
    {
      "segments": [
        1,
        2,
        3,
        4,
        5
      ],
      "goal": "Describe the main categories of AR hardware, explaining their components, examples, interaction or display operation, application domains, and relevant open issues.",
      "achieves": "It gives the learner a practical hardware framework for recognizing AR system types and for understanding the hardware constraints that affect later XR system design and implementation."
    }
  ],
  "goal": "Explain the main categories of AR hardware, including their components, examples, operation, application domains, and relevant open issues, and distinguish AR headsets from VR headsets.",
  "achieves": "It equips the learner with foundational AR hardware knowledge for understanding and evaluating AR systems, supporting the course aim of understanding and implementing an XR system with confidence."
}

{
  "objectives": [
    {
      "segments": [1, 2],
      "goal": "Explain how contextual inquiry is organized as a staged observational method, including active and passive modes, the master-apprentice observer stance, and reflection through affinity diagrams.",
      "achieves": "This lets the learner collect usability evidence from users in real task contexts and prepare that evidence for requirement-gathering work in an XR system development case study."
    },
    {
      "segments": [3, 4],
      "goal": "Apply affinity diagrams to group contextual inquiry notes and observations into design recommendations and requirement categories while distinguishing requirements from implementation choices.",
      "achieves": "This lets the learner convert observed user needs into usable requirement specifications for later design and implementation of an XR system."
    }
  ],
  "goal": "Explain contextual inquiry and apply affinity diagrams to convert observed user behavior into usability requirements and design recommendations.",
  "achieves": "This gives the learner a user-centered method for moving from requirement gathering to usability specification during XR system development."
}

{
  "objectives": [
    {
      "segments": [1, 2, 3, 4, 5, 6],
      "goal": "Explain how navigation in an immersive XR experience is composed of travel and wayfinding, including the main locomotion techniques and wayfinding supports that enable it.",
      "achieves": "It gives the learner a framework for analyzing the travel and wayfinding choices that shape an immersive system's user experience."
    },
    {
      "segments": [7],
      "goal": "Describe the interaction techniques used to issue commands and change the state or mode of an XR system.",
      "achieves": "It lets the learner specify how users will control the system, connecting navigation design to overall system-control design."
    }
  ],
  "goal": "Describe how navigation and system-control interaction are designed in an immersive XR experience.",
  "achieves": "It supports the course aim of building an XR system with confidence by giving the learner a design-level understanding of core movement and control functions."
}

{
  "objectives": [
    {
      "segments": [1, 2, 3, 4],
      "goal": "Explain the purpose of a virtual reality system as the challenge of producing presence through an immersive artificial environment.",
      "achieves": "It gives the learner a foundational framework for analyzing XR issues from both technological and user-experience perspectives."
    }
  ],
  "goal": "Explain the core issues of virtual reality systems as the challenge of producing presence through an immersive artificial environment.",
  "achieves": "It provides the foundational human-factors concepts for understanding later XR issues and user experience."
}

{
  "objectives": [
    {
      "segments": [1, 2, 3],
      "goal": "Describe the perceptual and psychoacoustic principles behind XR sound design.",
      "achieves": "It gives the learner a basis for evaluating how XR sound effects are selected and adjusted according to human auditory perception, supporting the course's human factors focus."
    },
    {
      "segments": [4, 5],
      "goal": "Explain the principles and rendering techniques behind localized binaural sound in XR.",
      "achieves": "It helps the learner understand how spatial audio supports presence when evaluating or developing an XR system."
    }
  ],
  "goal": "Explain how human auditory perception and binaural sound localization are used to design and render immersive sound in XR.",
  "achieves": "It gives the learner foundational human-factors knowledge for evaluating and implementing the auditory component of an XR system, supporting the course's aim of building immersive XR systems with confidence."
}

{
  "objectives": [
    {
      "segments": [1],
      "goal": "Explain what cybersickness/VIMS is, including the symptoms that indicate its onset and why reducing it matters for VR usability.",
      "achieves": "Gives the learner the foundational terminology and rationale for treating cybersickness as a human-factor barrier to VR acceptance and usable XR design."
    },
    {
      "segments": [2, 3],
      "goal": "Describe how internal user-related factors and external hardware factors can cause or increase cybersickness.",
      "achieves": "Lets the learner identify cybersickness risk factors from both user and device perspectives, supporting the course aim of addressing XR issues from user and developer viewpoints."
    }
  ],
  "goal": "Explain cybersickness/VIMS, the symptoms that indicate its onset, why reducing it matters, and the internal and hardware factors that can cause or increase it.",
  "achieves": "Equips the learner with foundational knowledge of a key psycho-physiological and technological issue in XR, enabling them to assess and address cybersickness when understanding or implementing an XR system."
}

{
  "objectives": [
    {
      "segments": [1, 2, 3],
      "goal": "Clarify the meanings of XR, VR, AR, and MR by explaining XR as an umbrella for immersive technologies and experiences and placing VR, AR, and MR on the reality-virtuality continuum.",
      "achieves": "It gives learners the shared conceptual vocabulary needed to follow the course's later XR hardware, software, and human-factors content."
    },
    {
      "segments": [4],
      "goal": "Explain why XR is an important emerging field by citing market growth, application domains, the metaverse, and demand for skilled practitioners.",
      "achieves": "It supports the course aim of preparing learners to understand and implement XR systems by motivating the relevance and opportunities of foundational XR knowledge."
    }
  ],
  "goal": "Explain how XR, VR, AR, and MR are understood within immersive technology and the reality-virtuality continuum, and why XR is an important emerging field.",
  "achieves": "It provides the introductory conceptual foundation and motivation needed to follow the course's XR hardware, software, human-factors, and system-development topics."
}

{
  "objectives": [
    {
      "segments": [1, 2, 3],
      "goal": "Explain the perceptual and technological basis of somatosensory and haptic immersion in XR.",
      "achieves": "Gives the learner a foundation for connecting human touch and body perception with XR haptic-feedback technologies when understanding or implementing an immersive XR system."
    },
    {
      "segments": [4],
      "goal": "Describe the possibilities and limitations of smell and taste simulation in XR.",
      "achieves": "Helps the learner evaluate olfactory and gustatory channels as part of full XR immersion when understanding or implementing an XR system."
    }
  ],
  "goal": "Explain how somatosensory, haptic, smell, and taste senses can shape and be simulated in XR immersion.",
  "achieves": "Provides the learner with the foundation to recognize the non-visual and non-auditory channels available for XR immersion and their technical limitations, supporting the course aim of understanding and implementing XR systems with confidence."
}

{
  "objectives": [
    {
      "segments": [1, 2],
      "goal": "Explain why XR interaction and perceptual design must account for human perception and why inconsistent virtual stimulation can produce adaptation or cybersickness.",
      "achieves": "Gives the learner the human-factors rationale for studying presence, perceptual design, and cybersickness in XR systems."
    },
    {
      "segments": [3, 4, 5],
      "goal": "Describe the perceptual-psychology and sensory basis of XR, including the human senses' stimuli, receptors, sense organs, and selective detection.",
      "achieves": "Provides the physiological and perceptual foundation for later lectures on vision, auditory experience, balance, and other senses in XR."
    }
  ],
  "goal": "Explain why XR design depends on human perception and describe the perceptual-psychology and sensory-system foundations it relies on.",
  "achieves": "Provides the learner with the human-factors foundation needed to understand later XR perception topics and to design or evaluate XR systems more effectively."
}

{
  "objectives": [
    {
      "segments": [1, 2],
      "goal": "Explain why usable interactive XR systems require a structured, user-centered software development lifecycle.",
      "achieves": "Gives the learner a rationale for approaching XR development systematically, preparing them to follow the course's case-study-based development stages."
    },
    {
